<template>
  <div class="query-selector" :class="{ open: isOpen }">
    <ul class="query-options">
      <li
        v-for="(option, index) in props.options"
        :key="index"
        class="query-option"
        :class="{ active: activeIndex === index }"
        @click="setQuery(index, option.query)"
      >
        {{ option.label }}
      </li>
    </ul>
    <div class="cur-label" @click="isOpen = !isOpen">
      {{ curLabel }}
      <span class="arrow"></span>
    </div>
  </div>
</template>

<script setup>
import { ref, defineProps } from 'vue';
import { useConfigStore } from '@/stores/config';
import { useToast } from 'vue-toastification';

const props = defineProps({
  options: {
    type: Array,
    required: true,
  }
});
const store = useConfigStore();
const isOpen = ref(false);
const activeIndex = ref(0);
const curLabel = ref(props.options[0].label);

const setQuery = (index, query) => {
    if (store.isLoading) {
      useToast().info("请等待加载完成!");
    }else{
      activeIndex.value = index;
      curLabel.value = props.options[index].label;
      store.searchQuery = query;
      isOpen.value = !isOpen.value;
    }
   
};
</script>

<style scoped lang="less">
@keyframes scale-grow {
  0% {
    transform: scale(1.05);
  }
  100% {
    transform: scaleX(1.1) scaleY(1.35);
  }
}

.query-selector {
  position: fixed;
  bottom: 28px;
  right: 56px;
  z-index: 10;
  width: 335px;
  height: 55px;
  .cur-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 14px;
    width: 100%;
    height: 100%;
    border: 2px solid #000;
    box-shadow:
      inset 1px 1px 1px rgba(255, 255, 255, 0.3),
      inset 0 0 0 4px @border-color; 
    border-radius: 50px;
    background: url('@/assets/svg/point.svg') center repeat;
    background-size: 6px;
    background-color: #000;
    cursor: pointer;
    font-size: 1.125rem;
    .arrow {
      border-left: 8px solid transparent;
      border-right: 8px solid transparent;
      border-top: 8px solid @text-primary-color;
      border-bottom: none;
      border-radius: 8px;
    }
  }
  .query-options {
    width: 100%;
    background-color: @bg-secondary-color;
    list-style: none;
    padding: 5px;
    border-radius: 20px;
    position: absolute;
    bottom: 30px;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s;
    .query-option {
      align-items: center;
      display: flex;
      width: 100%;
      border-radius: 50px;
      padding: 0 12px;
      height: 50px;
      cursor: pointer;
      font-size: 1.125rem;
      &.active{
          animation: background-glow 1s linear infinite alternate;
        }
      &:active {
        color: @text-secondary-color;
      }
    }
  }
}

.query-selector.open {
  .query-options {
    opacity: 1;
    bottom: 60px;
    visibility: visible;
    
  }
  .cur-label {
    .arrow{
      border-left: 8px solid transparent;
      border-right: 8px solid transparent;
      border-bottom: 8px solid @text-primary-color;
      border-top: none;
    }
    &::after {
      content: '';
      position: absolute;
      inset: 0;
      z-index: -2;
      border-radius: 50px;
      animation: background-glow 1s linear infinite alternate,
                  scale-grow 0.3s cubic-bezier(0.35, 0.7, 0, 0.7) infinite alternate;
    }
  }
}

@media (max-width: 1080px){
  .query-selector {
    left: 50%;
    bottom: 24px;
    right: auto;
    transform: translateX(-50%);
  }
}
</style>